changeSet.sql:

CREATE TABLE job_execution
(
    id UUID PRIMARY KEY,
    job_name VARCHAR(100) NOT NULL,
    status VARCHAR(20) NOT NULL,
    trigger_type VARCHAR(20) NOT NULL,
    started_at TIMESTAMPTZ NOT NULL,
    finished_at TIMESTAMPTZ
);

CREATE INDEX idx_job_execution_job_name
    ON job_execution(job_name);

CREATE INDEX idx_job_execution_started_at
    ON job_execution(started_at);

CREATE UNIQUE INDEX uq_job_execution_running
    ON job_execution(job_name)
    WHERE status = 'RUNNING';
